create table if not exists team_roles (id bigserial primary key, organization_id uuid not null references organizations(id) on delete cascade, name text not null, department text, permissions jsonb not null default '{}', hidden_fields jsonb not null default '[]', created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(organization_id, name));
create table if not exists time_entries (id bigserial primary key, organization_id uuid not null references organizations(id) on delete cascade, user_id uuid not null references users(id) on delete cascade, project_id bigint references projects(id) on delete set null, task_id bigint references tasks(id) on delete set null, started_at timestamptz, ended_at timestamptz, minutes integer not null default 0 check (minutes >= 0), billable boolean not null default false, status text not null default 'pending', notes text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists team_messages (id bigserial primary key, organization_id uuid not null references organizations(id) on delete cascade, sender_id uuid references users(id) on delete set null, project_id bigint references projects(id) on delete cascade, body text not null, important boolean not null default false, read_by jsonb not null default '[]', created_at timestamptz not null default now());
create index if not exists idx_team_roles_org on team_roles(organization_id);
create index if not exists idx_time_entries_org_user on time_entries(organization_id, user_id, created_at desc);
create index if not exists idx_team_messages_org_created on team_messages(organization_id, created_at desc);
